Read the source rows from column A onward, using column I as the sequence number and column H as the code. Fill the K:U answer block in rows of four (number, code) pairs, leaving separator and unused cells empty. Save only the computed values into Sheet1 without touching other cells.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

SHEET = "Sheet1"

if SHEET in vals.sheetnames:
    vws = vals[SHEET]
else:
    vws = vals.active

if SHEET in wb.sheetnames:
    ws = wb[SHEET]
else:
    ws = wb.create_sheet(SHEET)

def normalize_number(x):
    if x is None:
        return None
    if isinstance(x, bool):
        return x
    if isinstance(x, float) and x.is_integer():
        return int(x)
    if isinstance(x, str):
        s = x.strip()
        if not s:
            return None
        try:
            f = float(s)
            return int(f) if f.is_integer() else f
        except ValueError:
            return s
    return x

records = []
for r in range(2, vws.max_row + 1):
    a = vws.cell(r, 1).value
    h = vws.cell(r, 8).value
    i = vws.cell(r, 9).value

    if a is None and h is None and i is None:
        continue

    num = normalize_number(i)
    if num is None:
        num = len(records) + 1

    code = h
    if isinstance(code, str):
        code = code.strip()
        if code == "":
            code = None

    records.append((num, code))

# Answer region: K2:U10
first_row, last_row = 2, 10
first_col, last_col = 11, 21  # K through U

# Clear the answer region first so unused/separator cells are truly empty.
for r in range(first_row, last_row + 1):
    for c in range(first_col, last_col + 1):
        ws.cell(r, c).value = None

# Fill four (number, code) pairs per row:
# K/L, N/O, Q/R, T/U
for r in range(first_row, last_row + 1):
    base = (r - first_row) * 4
    for p in range(4):
        idx = base + p
        if idx < len(records):
            num, code = records[idx]
            num_col = first_col + 3 * p
            code_col = num_col + 1
            ws.cell(r, num_col).value = num
            ws.cell(r, code_col).value = code

wb.save(OUT)

print("records:", len(records))
print("row4 K:U:", [ws.cell(4, c).value for c in range(11, 22)])
print("row7 K:U:", [ws.cell(7, c).value for c in range(11, 22)])
```

